\label{lemma-geometrically-normal-stein}
Let $k$ be a field. Let $X$ be a proper geometrically normal scheme over $k$.
The following are equivalent
\begin{enumerate}
\item $H^0(X, \mathcal{O}_X) = k$,
\item $X$ is geometrically connected,
\item $X$ is geometrically irreducible, and
\item $X$ is geometrically integral.
\end{enumerate}

\label{lemma-tangent-space}
The set of dotted arrows making (\ref{equation-tangent-space}) commute
has a canonical $\kappa(x)$-vector space structure.

\label{lemma-regular-functions-proper-variety}
Let $X$ be a proper variety over $k$. Then
\begin{enumerate}
\item $K = H^0(X, \mathcal{O}_X)$ is a field which is
a finite extension of the field $k$,
\item if $X$ is geometrically reduced, then $K/k$ is separable,
\item if $X$ is geometrically irreducible, then $K/k$
is purely inseparable,
\item if $X$ is geometrically integral, then $K = k$.
\end{enumerate}

\label{lemma-smooth-regular}
\begin{slogan}
Smooth over a field implies regular
\end{slogan}
Let $X \to \Spec(k)$ be a smooth morphism where $k$ is a field.
Then $X$ is a regular scheme.

\label{lemma-easy-ff}
Let $R$ be a ring.
Let $M$ be an $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is faithfully flat, and
\item $M$ is flat and for all $R$-module homomorphisms $\alpha : N \to N'$
we have $\alpha = 0$ if and only if $\alpha \otimes \text{id}_M = 0$.
\end{enumerate}

\label{lemma-reflexive-over-normal}
Let $X$ be an integral locally Noetherian normal scheme.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item $\mathcal{F}$ is torsion free and has property $(S_2)$, and
\item there exists an open subscheme $j : U \to X$ such that
\begin{enumerate}
\item every irreducible component of $X \setminus U$
has codimension $\geq 2$ in $X$,
\item $j^*\mathcal{F}$ is finite locally free, and
\item $\mathcal{F} = j_*j^*\mathcal{F}$.
\end{enumerate}
\end{enumerate}

\label{lemma-geometrically-reduced-at-point}
\begin{slogan}
Geometric reducedness can be checked on local rings.
\end{slogan}
Let $k$ be a field.
Let $X$ be a scheme over $k$.
Let $x \in X$.
The following are equivalent
\begin{enumerate}
\item $X$ is geometrically reduced at $x$, and
\item the ring $\mathcal{O}_{X, x}$ is geometrically
reduced over $k$ (see
Algebra, Definition \ref{algebra-definition-geometrically-reduced}).
\end{enumerate}

\label{lemma-scheme-theoretically-dense-contain-embedded-points}
Let $X$ be a locally Noetherian scheme. Let $U \subset X$ be an
open subscheme. The following are equivalent
\begin{enumerate}
\item $U$ is scheme theoretically dense in $X$
(Morphisms, Definition \ref{morphisms-definition-scheme-theoretically-dense}),
\item $U$ is dense in $X$ and $U$ contains all embedded points of $X$, and
\item $U$ contains all associated points of $X$.
\end{enumerate}

\label{lemma-descending-property-open-immersion}
The property $\mathcal{P}(f) =$``$f$ is an open immersion''
is fpqc local on the base.

\label{lemma-descending-property-quasi-affine}
The property $\mathcal{P}(f) =$``$f$ is quasi-affine''
is fpqc local on the base.

\label{lemma-norm-quasi-affine}
Let $\pi : X \to Y$ be a finite morphism of schemes. Assume $X$ is quasi-affine
and there exists a norm of degree $d$ for $\pi$. Then $Y$ is quasi-affine.

\label{lemma-constructible-stable-specialization-closed}
Let $R$ be a ring. Let $E \subset \Spec(R)$ be a constructible subset.
\begin{enumerate}
\item If $E$ is stable under specialization, then $E$ is closed.
\item If $E$ is stable under generalization, then $E$ is open.
\end{enumerate}

statement:
Here constructible means a finite union of sets U minus V with U,V retrocompact open in Spec R; equivalently finite Boolean combinations of quasi-compact opens. Let $R$ be a ring. Let $E \subset \Spec(R)$ be a constructible subset.
\begin{enumerate}
\item If $E$ is stable under specialization, then $E$ is closed.
\item If $E$ is stable under generalization, then $E$ is open.
\end{enumerate}

